---@param isNotPlay boolean 是否播放弯腰动作
function OverseaManageMainSecondDialog:PlayRoleAni(isNotPlay)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local id = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    if id ~= 0 then
        ---@type CardComponent
        local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        ---@type CardDojo
        local cardDojo = cardComp:GetCardById(id)
        ---设置心情值和状态 会刷新
        local point = tonumber(cardDojo.cafeEnergy) or 0
        if point == 0 then
            if not isNull(self.curAnimator) then
                self.curAnimator:SetInteger("action",2)
            end
        else
            if not isNull(self.curAnimator) and not isNotPlay then
                self.curAnimator:SetInteger("action",1)
                coroutine.yield(Yielders.EndOfFrame)
                self.curAnimator:SetInteger("action",0)
            end
        end
    end
end

function OverseaManageMainSecondDialog:ResetCameraLayer()
    local camera = KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer("role_shadowcaster"))
    if isNull(camera) then
        ----说明不存在这个层的相机，要设置一次
        local curScene = SceneManagement:GetInstance():Current()
        local cameraOrigin = curScene:GetCacheObjectByName('Camera')
        if cameraOrigin then
            local urpBase = cameraOrigin:GetComponent(typeof(URPBaseCamera))
            if urpBase then
                urpBase:CopyCamera()
            end
        end
    end
end

