function OverseaManageMainSecondDialog:RequestData()
    self.isLoadSuccess = false
    self.isRequestSuccess = false
    GameUtils.Request(Interfaces.MaidCoffeeHome, {}, function(req, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local data = checkTable(response.data)
        ---@type MaidCoffeeComponent
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        component:InitialDojo(data)
        --MaidCoffeeMgr:GetInstance():StartMenuTimer()
        self.isRequestSuccess = true
    end)
    while (not self.isRequestSuccess) do
        coroutine.yield()
    end
    self:LoadCafePrefab()
    self:LoadManageModel()
    self:LoadCatModel()
end

function OverseaManageMainSecondDialog:DeleteCatGameObject()
    if not isNull(self._catGo) then
        KTool.SafeDelete(self._catGo, true)
    end
    self._catGo = nil
end

function OverseaManageMainSecondDialog:LoadCatModel()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local showCatId = component:GetShowCatId()
    if  checkNumber(self.curShowCatId) ~= showCatId then
        self.curShowCatId = showCatId
        self:DeleteCatGameObject()
        if self.curShowCatId ~= 0 then
            local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
            ---@type CatBallUtils
            local CatBallUtils                = import("Game.CatBall.CatBallUtils")
            local dojo = eggComponent:GetCat(self.curShowCatId)
            local catVo = CatBallUtils.GetCatBallVo(dojo.catId)
            local genes = catVo.kind
            if not self.catPos then
                self.catPos = self.sceneNode.transform:Find("ScenePositionNode/CatPos")
            end
            self:StopCoroutine()
            self._co = cs_coroutine.start(function()
                eggComponent:LoadCatModelAsync(MaidCoffeeConstants.BornType.Adult, checkString(catVo.catId), false, genes, self.catPos.gameObject, function(go)
                    ---@type UnityEngine.Transform
                    local trans = go.transform
                    go.name = tostring(dojo.catId)
                    trans.localPosition = Vector3.New(0,0,0)
                    trans.localRotation = Quaternion.Euler(0, 0, 0)
                    trans.localScale = Vector3.New(1,1,1)
                    KTool.SetParent(go,self.catPos.gameObject,true)
                    self._catGo = go
                end)
            end)
        end
    end
end

function OverseaManageMainSecondDialog:StopCoroutine()
    if self._co then
        cs_coroutine.stop(self._co)
    end
    self._co = nil
end

function OverseaManageMainSecondDialog:LoadManageModel()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local id = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    ---检测一下当前位置是否有人 有人的话 就下掉
    local pos = MaidCoffeeConstants.SelectType.Manager * 100 + 1
    if id == 0 then
        if self.personModels and self.personModels[pos] then
            self:RemoveCloudPrefabToRoot()
            GameObject.Destroy(self.personModels[pos].go)
            self.personModels[pos] = nil
        end
        Events.Broadcast("MaidCoffeeRefreshManagerStatus",true)
        return
    end
    Events.Broadcast("MaidCoffeeRefreshManagerStatus",false)
    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    ---@type CardDojo
    local cardDojo = cardComp:GetCardById(id)
    local cardInfoVo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
    local offsetY = cardInfoVo.coordinate
    if not self.managePos then
        self.managePos = self.sceneNode.transform:Find("ScenePositionNode/ManagePos")
    end
    ---说明位置上有人
    if self.personModels[pos] then
        ---ID如果一样 不处理
        if  self.personModels[pos].id ~= id then
            self:RemoveCloudPrefabToRoot()
            GameObject.Destroy(self.personModels[pos].go)
            self.personModels[pos] = nil
            ---再上新的人
            self:LoadPrefabById(id,pos,offsetY,cardInfoVo.cloudPoint,cardDojo)
        end
    else
        self:LoadPrefabById(id,pos,offsetY,cardInfoVo.cloudPoint,cardDojo)
    end

end

function OverseaManageMainSecondDialog:LoadPrefabById(id,pos,offsetY,cloudPath,cardDojo)
    self.roleId = id
    ---没人的时候 把这个人放上去
    local path = MaidCoffeeUtils.GetCardModelPathById(cardDojo)
    ResourceModule.LoadBundleAsync(path, function(_loader, isOk, resultObject)
        if isOk then
            local managerModelGo = _loader:Instantiate()
            KTool.SetParent(managerModelGo,self.managePos.gameObject,false)
            KTool.GetOrAddComponent(managerModelGo.gameObject,typeof(CS.CustomLightDirRelativeCamera))
            managerModelGo.transform.localPosition = Vector3(managerModelGo.transform.localPosition.x, managerModelGo.transform.localPosition.y + offsetY, managerModelGo.transform.localPosition.z)
            self.personModels[pos] = {id = id , go = managerModelGo}
            ---绑定动画状态机
            self:LoadAnimatorControllerAndFillController(id,managerModelGo,cardDojo)
            self:LoadCloudById(id,managerModelGo,cloudPath)
        end
    end)
end

function OverseaManageMainSecondDialog:RefreshManageRoleStatus(id)
    if isNull(self.roleId) or self.roleId ~= id then
        return
    end
    self:PlayRoleAni()
    
    local pos = MaidCoffeeConstants.SelectType.Manager * 100 + 1
    local go = self.personModels[pos].go
    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComp:GetCardById(id)
    local cardInfoVo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
    self:LoadCloudById(self.roleId, go, cardInfoVo.cloudPoint)
end

function OverseaManageMainSecondDialog:LoadCloudById(id,go,path)
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById(tonumber(id))
    ---设置心情值和状态 会刷新
    local point = tonumber(cardDojo.cafeEnergy) or 0
    if point == 0 then
        local parent = go.transform:Find(path)
        if not isNull(parent) then
            if not self.cloudPrefab then
                ResourceModule.LoadBundleAsync(MaidCoffeeConstants.CloudRainPath, function(_loader, isOk, resultObject)
                    if isOk then
                        local cloudPrefab = _loader:Instantiate()
                        KTool.SetParent(cloudPrefab.gameObject,parent.gameObject,false)
                        cloudPrefab.transform.localPosition = Vector3.New(-0.12,0,0)
                        self.cloudPrefab = cloudPrefab
                    end
                end)
            else
                KTool.SetActive(self.cloudPrefab.gameObject,true)
                KTool.SetParent(self.cloudPrefab.gameObject,parent.gameObject,false)
            end
        end
    else
        self:RemoveCloudPrefabToRoot()
    end
end

function OverseaManageMainSecondDialog:RemoveCloudPrefabToRoot()
    if not isNull(self.cloudPrefab) then
        KTool.SetActive(self.cloudPrefab.gameObject,false)
        KTool.SetParent(self.cloudPrefab.gameObject,self.sceneNode.gameObject,false)
    end
end

function OverseaManageMainSecondDialog:LoadAnimatorControllerAndFillController(id,go,cardDojo)
    if isNull(go) then return end
    local prefabPath = MaidCoffeeUtils.GetCardAnimatorControllerPathByDojo(cardDojo)
    if prefabPath then
        local loader = ResourceModule.LoadBundleAsync(prefabPath, nil, true)
    --[[    if not self.cacheControllerLoader[id] then
            loader = ResourceModule.LoadBundleAsync(prefabPath, nil, true)
            self.cacheControllerLoader[id] = loader
        else
            loader = self.cacheControllerLoader[id]
        end]]
        cs_coroutine.start(function()
            ---@type UnityEngine.Animator
            local animator = KTool.GetOrAddComponent(go, typeof(CS.UnityEngine.Animator))
            self.curAnimator = animator
            while not loader.IsCompleted do
                coroutine.yield()
            end
            if loader.IsSuccess then
                local ins = CS.UnityEngine.Object.Instantiate(loader.ResultObject)
                animator.runtimeAnimatorController = ins
                loader:Retain(ins)
            end
            loader:Release()
        end )
    end
end

function OverseaManageMainSecondDialog:LoadCafePrefab()
    local path = "Prefabs/Runtime/MaidCoffee_easy.prefab"
    local oldScene = nil
    if not KTool.IsNull(self.sceneNode) then
        if self.sceneNode.name == string.stripExtension(string.stripFileName(path)) then
            return
        else
            oldScene = self.sceneNode
        end
    end
    local loader = self.loaderMap[path]
    if loader == nil then
        ---@type Engine.Modules.AbstractResourceLoader
        loader = ResourceModule.LoadBundleSync(path, nil, true)
        while not loader.IsSuccess do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end

        if not loader.IsSuccess then
            loader:Release()
        else
            self.loaderMap[path] = loader
        end
    end

    if loader and loader.IsSuccess then
        self.sceneNode = loader:Instantiate()
        if not KTool.IsNull(self.sceneNode) then
            --sceneNode会被放到当前的activeScene，如果那个activeScene被卸载，那么sceneNode会被提前销毁
            local sceneInstance = SceneManagement:GetInstance():GetSceneInstance(Constants.IdSceneSetting45)
            if not isNull(sceneInstance) then
                local name = sceneInstance._unityScene.name
                if not isNull(name) and not string.isEmpty(name) then
                    local targetScene = SceneManager.GetSceneByName(name)
                    if targetScene then
                        SceneManager.MoveGameObjectToScene(self.sceneNode, targetScene)
                    end
                end
            end
            self.sceneNode.name = string.stripExtension(string.stripFileName(path))
        end
        local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local List = maidCoffeeComponent:GetSaveCattyRenovatedList()
        local loaders = {}
        for i, v in pairs(List) do
            local vo = MaidCoffeeUtils.GetRenovateInfoVo(v)
            if not isNull(vo) and vo.isLoad then
                local path = vo.prefab
                local tempLoader = ResourceModule.LoadBundleAsync(path, function(_loader, isOk, resultObj)
                    if isOk then
                        self.nameToNode[v] = _loader:Instantiate()
                        _loader:Release()
                        KTool.SetParent(self.nameToNode[v], self.sceneNode)
                        self.nameToNode[v].transform.localPosition = Vector3.New(0, 0, 0)
                    end
                end, true)
                table.insert(loaders,tempLoader)
            end
        end

        while #loaders > 0 do
            for i = #loaders, 1 , -1 do
                if not loaders[i].IsError and loaders[i].IsSuccess then
                    table.remove(loaders,i)
                end
            end
            coroutine.yield()
        end

        self.isLoadSuccess = true
        if oldScene then
            GameObject.Destroy(oldScene)
        end

        self:InitTvNodeEnv()
        self:InitVirCamNode()
        CfUtils.CookieSave("IsCafeLoadSuccess",1)
    end
end


function OverseaManageMainSecondDialog:OnCaptureAction()
    -- capture screen
    local effectBg = self.controller.gameObject:GetComponent(typeof(UIEffectCapturedImage))
    if effectBg then
        effectBg:Capture()
    end
    cs_coroutine.yield_return(Yielders.EndOfFrame)
end

function OverseaManageMainSecondDialog:InitVirCamNode()
    if self.sceneNode then
        local cam = self.sceneNode.transform:Find(VirCamNodeName)
        self.virCam = cam
        KTool.SetActive(self.virCam.gameObject,true)
    end
end

function OverseaManageMainSecondDialog:SetVirCamState(state)
    if isNull(self.virCam) then
        self:InitVirCamNode()
    end
    if isNull(self.virCam) then
        return
    end
    local barCam = self.virCam.transform:Find("Cam_Manage")
    local personCam = self.virCam.transform:Find("Cam_Person")
    KTool.SetActive(barCam.gameObject,state)
    KTool.SetActive(personCam.gameObject,not state)
end

function OverseaManageMainSecondDialog:RefreshRedPoint()
    local isCattyUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3010)
    if isCattyUnLock then
        GameUtils.BindRedPoint(Constants.RedPointConst.MaidCafeLevelUp, self.BtnCatty ,true)
    end

    GameUtils.BindRedPoint(Constants.RedPointConst.MaidCafeStaff, self.BtnPersonnel ,true)


    local isCatBallUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3013)
    if isCatBallUnLock then
        GameUtils.BindRedPoint(Constants.RedPointConst.MaidCafeCatBall, self.BtnCatball ,true)
    end

    local isRenovaUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3012)
    if isRenovaUnLock then
        local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local isHaveRedPoint = maidCoffeeComponent:IsShowAvatarsNew()
        KTool.SetActive(self.RenovaNew.gameObject,isHaveRedPoint)
    else
        KTool.SetActive(self.RenovaNew.gameObject,false)
    end

    if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3007) then
        GameUtils.BindRedPoint(Constants.RedPointConst.MainCafeCatBallEnter, self.BtnCatBallListEnter, true)
        ---@type CatBallUtils
        local CatBallUtils = import("Game.CatBall.CatBallUtils")
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainCafeCatBallEnterList, CatBallUtils.GetHomeRedPointNum())
    end
    local isCallOnUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id266)
    if isCallOnUnLock then
        GameUtils.BindRedPoint(Constants.RedPointConst.MaidCafeBusiness, self.BtnMerchantRed ,true)
    end
end

function OverseaManageMainSecondDialog:RemoveRedDot()
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MaidCafeLevelUp)
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MaidCafeCattyMain)
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MaidCafeStaff)
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MaidCafeCatBall)
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MaidCafeBusiness)
end

function OverseaManageMainSecondDialog:RefreshBtnState()
    local isCattyUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3010)
    KTool.SetActive(self.BtnCattyLock, (not isCattyUnLock))
    KTool.SetActive(self.StarGroup,isCattyUnLock)

    local isRenovaUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3012)
    KTool.SetActive(self.BtnRenovaLock,not isRenovaUnLock)
    local alpha = isRenovaUnLock and 1 or 0.5
    self:SetBtnCanvasAlpha(self.BtnRenova,alpha)

    local isFoodUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3002)
    KTool.SetActive(self.BtnFoodLock,not isFoodUnLock)
    local alpha = isFoodUnLock and 1 or 0.5
    self:SetBtnCanvasAlpha(self.BtnFood,alpha)

    local isLoungeUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3005)
    KTool.SetActive(self.BtnLoungeLock,not isLoungeUnLock)
    local alpha = isLoungeUnLock and 1 or 0.5
    self:SetBtnCanvasAlpha(self.BtnLounge,alpha)

    local isTipStoreUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id253)
    KTool.SetActive(self.BtnTipLock,not isTipStoreUnLock)
    local alpha = isTipStoreUnLock and 1 or 0.5
    self:SetBtnCanvasAlpha(self.BtnTip,alpha)

    local isCatUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3013)
    KTool.SetActive(self.BtnCatballLock, (not isCatUnLock))

    ---如果解锁了  要看是否放上了猫球
    if isCatUnLock then
        self:RefreshCatBallState()
    end

    local isCatBallUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3013)
    KTool.SetActive(self.BtnCatball.transform.parent.gameObject,isCatBallUnLock)

    local isCallOnUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id266)
    KTool.SetActive(self.BtnMerchant,  isCallOnUnLock)
    if isCallOnUnLock then
        self:RefreshCallOnBtnShow()
    end

    local isCatBallListUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3007)
    KTool.SetActive(self.BtnCatBallListEnterLockGroup, not isCatBallListUnLock)
    local alpha = isCatBallListUnLock and 1 or 0.5
    self:SetBtnCanvasAlpha(self.BtnCatBallListEnter,alpha)

end

function OverseaManageMainSecondDialog:RefreshCallOnBtnShow()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local data = maidCoffeeHomeDojo:GetMerchantData()
    if not isNull(data) and not isNull(data.merchant) and next(data.merchant) then
        CfUtils.FillText(self.TxtTitle,data.merchant.name)
        local path = CS.ParseUtils.ParsePathNameByData(data.merchant.icon)
        CfUtils.FillImage(self.ImgHeadIcon,path)

        local remainTime = data.merchant.remainTime - os.time()
        self:RemoveTimer()
        if remainTime > 0 then
            CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS2(checkNumber(remainTime)))
            if remainTime > 0 then
                self.merchantTimer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
                    if count > 0 then
                        CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS2(checkNumber(count)))
                    else
                        CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS2(checkNumber(0)))
                        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.merchantTimer)
                        self.merchantTimer = nil
                    end
                end, remainTime + 1, false, true)
            end
        end
    end
end

function OverseaManageMainSecondDialog:RemoveTimer()
    if self.merchantTimer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.merchantTimer)
        self.merchantTimer = nil
    end
end

function OverseaManageMainSecondDialog:SetBtnCanvasAlpha(btnGo,alpha)
    local CanvasGroup = CS.UnityEngine.CanvasGroup
    local go = btnGo.transform:Find("Pellucidity")
    if go then
        local canvasGroup =  go.gameObject:GetComponent(typeof(CanvasGroup))
        if canvasGroup then
            if math.floor(canvasGroup.alpha) ~= alpha then
                canvasGroup.alpha = alpha
            end
        end
    end
end

function OverseaManageMainSecondDialog:RefreshCatBallState()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local showCatId = component:GetShowCatId()
    KTool.SetActive(self.CatAdd.gameObject,showCatId <= 0)
end

function OverseaManageMainSecondDialog:RequestReportTime()
    GameUtils.Request(Interfaces.MaidCoffeeMenuReport,{},function(request,response)
        if checkInt(response.errCode) == 0 then
            local data = response.data
            local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
            local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
            if maidCoffeeHomeDojo then
                maidCoffeeHomeDojo.reportTime = data.reportTime
                maidCoffeeHomeDojo.reportRewards = data.reportRewards
            end
            ---是否有收益
            local isHave = maidCoffeeComponent:IsHaveReward()
            KTool.SetActive(self.ReportEffect.gameObject,isHave)
            GameUtils.UpdateServerRedPointData({cafeMenuEmpty = data.cafeMenuEmpty})
        end
    end)
end

function OverseaManageMainSecondDialog:SetNodePosition()
    if self.sceneNode then
        local go = self.sceneNode.transform:Find(ModelPositionName)
        local BtnGroup = {
            self.BtnTV,self.BtnReportPos,self.BtnPersonnelPos,self.BtnCattyPos,self.BtnCatballPos
        }

        for i, v in pairs(BtnGroup) do
            if v and go then
                local name = "3DPosition/UINode"..i
                local node = go.transform:Find(name).position
                local scenePos = CfUtils.WorldPosition2UIPosition(node, UIModule.RootCanvas.transform)
                v.anchoredPosition = Vector2.New(scenePos.x, scenePos.y)
            end
        end
    end
end

function OverseaManageMainSecondDialog:OnHide()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:OnCaptureAction()
        self:RemoveOpenPersonnelCo()
        self:RemovePosCo()
        self:CleanScene()
        CfUtils.CookieSave("IsCafeLoadSuccess", 0)
    end))
    return coWait
end

function OverseaManageMainSecondDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self:RemoveTimer()
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:Delete()
            self:ResetCamBlendTime()
            self = nil --lua层的gc需要
        end)
    end))
    return coWait
end

function OverseaManageMainSecondDialog:CleanScene()
    for _, loader in pairs(self.loaderMap) do
        loader:Release()
    end
    self.loaderMap = nil
    --self.cacheControllerLoader = nil

    for _, go in pairs(self.nameToNode) do
        if not KTool.IsNull(go) then
            GameObject.Destroy(go)
        end
    end
    self.nameToNode = nil

    for _, go in pairs(self.personModels)  do
        if not KTool.IsNull(go) then
            GameObject.Destroy(go)
        end
    end
    self.personModels = nil

    if not isNull(self.cloudPrefab) then
        GameObject.Destroy(self.cloudPrefab.gameObject)
        self.cloudPrefab = nil
    end

    self:StopCoroutine()
    self:DeleteCatGameObject()

    if not KTool.IsNull(self.sceneNode) then
        GameObject.Destroy(self.sceneNode)
        self.sceneNode = nil
    end

    if self.changeRoleModelEvent then
        Events.RemoveListener("MaidCoffee_PersonChange",self.changeRoleModelEvent)
        self.changeRoleModelEvent = nil
    end

    if self.refreshVimCraEvent then
        Events.RemoveListener("MaidCoffee_VimCraStageChange",self.refreshVimCraEvent)
        self.refreshVimCraEvent = nil
    end

    if self.changeRoleRotationEvent then
        Events.RemoveListener("MaidCoffee_SetManageRotation",self.changeRoleRotationEvent)
        self.changeRoleRotationEvent = nil
    end

    if self.changeShowCatEvent then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.MaidCoffeeChangeShowCat,self.changeShowCatEvent)
        self.changeShowCatEvent = nil
    end

    if self.changeBarVimEvent then
        Events.RemoveListener("MaidCoffee_ChangeBarVim",self.changeBarVimEvent)
        self.changeBarVimEvent = nil
    end
    if self.soulPointRecoverEvent then
        Events.RemoveListener("MaidCoffee_RecoverSoulPoint",self.soulPointRecoverEvent)
        self.soulPointRecoverEvent = nil
    end
end

function OverseaManageMainSecondDialog:__delete()
