function OverseaManageMainSecondDialog:AutoOpenDialog()
    local isAuto = checkNumber(KCookie.Get("CafeIsAutoOpen"))
    if isAuto > 0 then
        cs_coroutine.start(function()
            KCookie.Set("CafeIsAutoOpen", 0)
            --coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.1))
            if not isNull(self.parameters.autoData)  then
                ---实际的界面id
                local row = self.parameters.autoData.row
                local moduleId = checkInt(row:Get("moduleID"))
                local parameter = checkInt(row:Get("parameter"))
                local id = isSet(self.parameters.autoData,"id") and self.parameters.autoData.id or nil
                if moduleId == Constants.UITypeIds.UIMaidCoffeeCookingMainDialog then
                    KTool.SetActive(self.virCam.gameObject,false)
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeCookingMainDialog, parameters = { type = MaidCoffeeConstants.CookingType.Cooking,tableIndex = parameter ,id = id,cb = function() end } })
                elseif moduleId == Constants.UITypeIds.UIMaidCoffeeManagerDialog then ---跳转到自己 不处理 加这个是防止下面的报错

                elseif moduleId == Constants.UITypeIds.UIMaidCoffeeCatBallDialog then  ---猫球经营
                    self:OnBtnCatballClick()
                elseif moduleId == Constants.UITypeIds.OverManegeLoungeMainDialog then
                    self:OnBtnLoungeClick()
                    ---营业报表  这个界面每天第一次会打开 可能会和逻辑冲突
                elseif moduleId == Constants.UITypeIds.UIMaidCoffeePersonMainDialog then
                    self.isAuto = true
                    KTool.SetActive(self.Root.gameObject,false)
                    self:OnBtnPersonnelClick()
                elseif moduleId == Constants.UITypeIds.UIMaidCoffeeCattyMain or moduleId == Constants.UITypeIds.UIMaidCoffeeMenuSettingDialog
                        or moduleId == Constants.UITypeIds.UIMaidCoffeeStatementDialog then
                    self:OpenDialogById(moduleId)
                else
                    printError("不存在咖啡厅的模块Id:%s",moduleId)
                end
            end
        end)
    end
end

